def quality(rms_uv: float, critical: bool) -> tuple[str, str]:
    """Returns (label, ansi_colour)."""
    if rms_uv < 1.0:
        return "NO CONTACT  ", _RED
    if rms_uv < 3.0:
        return "WEAK        ", _YLW
    if rms_uv <= 80.0:
        return "GOOD  ✓     ", _GRN
    if rms_uv <= 150.0:
        return "NOISY       ", _YLW if not critical else _RED
    return "VERY NOISY  ", _RED

