/* LCARS chrome shape pass: rounded outer-left corners + thick colored
   left rail rotating through the data palette. The 14px rail is the
   left border of the cell (with 1px on the other three sides), so it
   follows the cell's rounded corners and reads as an integral part of
   the panel — not a pseudo-element overlay. nth-child(6n+X) cycles
   through --data-cat-0..5 so adjacent cells show different "section
   colors", matching how LCARS panels color-code zones. */
.theme-lcars .cell {
  border-radius: 24px 4px 4px 24px;
  border-width: 1px 1px 1px 14px;
  border-style: solid;
  padding-left: 1.25rem;
}
.theme-lcars .cell:nth-child(6n+1) { border-left-color: var(--data-cat-0, #ff9900); }
.theme-lcars .cell:nth-child(6n+2) { border-left-color: var(--data-cat-1, #ffcc99); }

