def _session_count() -> int:
    try:
        return json.loads(_SESSION_FILE.read_text()).get("count", 0)
    except (OSError, json.JSONDecodeError):
        return 0


def _session_increment() -> None:
    _SESSION_FILE.write_text(json.dumps({"count": _session_count() + 1}))

def _cached_gif(name: str, gif_url: str) -> str:
    """Return path to a locally cached GIF, downloading if needed."""
    GIF_CACHE.mkdir(parents=True, exist_ok=True)
    dest = GIF_CACHE / f"{name}.gif"
    if dest.exists():
        return str(dest)
    req = urllib.request.Request(gif_url, headers={"User-Agent": "Mozilla/5.0"})
    with urllib.request.urlopen(req, timeout=10) as r, open(dest, "wb") as f:
        f.write(r.read())
    return str(dest)

