export function highlight(source, language, themeTokens) {
  const grammar = Prism.languages[language] ?? Prism.languages.plaintext;
  const tokens = Prism.tokenize(source, grammar);
  return renderTokens(tokens, themeTokens);
}

function renderTokens(tokens, themeTokens) {
  return tokens.map(tok => {
    if (typeof tok === 'string') return escapeHtml(tok);
    const color = themeTokens[tok.type] ?? themeTokens.default;
    return `<span style="color:${color}">${escapeHtml(String(tok.content))}</span>`;
  }).join('');
}

